/* Trip sheet / memo: trips with km, quantity and amount; advances; billed and unbilled expenses; diesel entries;
   door delivery; crew bata, incentive and timing; and the driver cash work-out. Loaded after fleetpay.js. */
'use strict';

const FL_LOADS = ['Seats', 'Parcel', 'Luggage', 'Seats + Parcel', 'Hire', 'Empty'];
const FL_EXP_HINTS = ['Toll', 'Entry fee', 'Parking', 'Police', 'RTO', 'Pooja', 'Loading', 'Unloading', 'Luggage', 'Grease', 'Air', 'Puncture', 'Wash', 'Food', 'Phone', 'Other'];
const FL_FUELS = ['Diesel', 'AdBlue', 'CNG'];
const flNum = x => +x || 0;
const flSumBy = (a, f) => a.reduce((s, x) => s + flNum(f(x)), 0);

/* The memo part of a trip sheet in one shape, whether it was saved in the new layout or the earlier one. */
function flMemo(s) {
  if (s.v === 2 || !s.sheet) return { adv: s.adv || [], billed: s.billed || [], unbilled: s.unbilled || [], fuel: s.fuel || [], door: s.door || [], crew: s.crew || {}, payMode: s.payMode || 'sheet', drvCollected: flNum(s.drvCollected), otherInc: flNum(s.otherInc), target: flNum(s.target), checks: s.checks || {}, startTime: s.startTime || '', reachTime: s.reachTime || '', legacyPaid: {} };
  const o = s.sheet || {}, d = s.date;
  return { adv: flNum(o.advance) ? [{ date: d, branch: '', details: '', amount: flNum(o.advance) }] : [],
    billed: FL_EXPENSES.filter(([k]) => !['beta1', 'beta2', 'attBeta'].includes(k) && flNum(o[k])).map(([k, l]) => ({ date: d, desc: l, pay: 'D', amount: flNum(o[k]) })), unbilled: [],
    fuel: [...(flNum(o.dieselL) || flNum(o.dieselAmt) ? [{ date: d, type: 'Diesel', bunk: '', ltrs: flNum(o.dieselL), rate: flNum(o.dieselL) ? Math.round(flNum(o.dieselAmt) / flNum(o.dieselL) * 100) / 100 : 0, amount: flNum(o.dieselAmt), pay: 'C' }] : []), ...(flNum(o.adblue) ? [{ date: d, type: 'AdBlue', bunk: '', ltrs: flNum(o.adblue), rate: 0, amount: 0, pay: 'C' }] : [])],
    door: [], crew: {}, payMode: 'payroll', drvCollected: 0, otherInc: FL_INCOME.reduce((t, [k]) => t + flNum(o[k]), 0), target: 0, checks: {}, startTime: o.startTime || '', reachTime: o.reachTime || '', legacyPaid: { d1: flNum(o.beta1), d2: flNum(o.beta2), cl: flNum(o.attBeta) } };
}
/* Every figure of a trip sheet: totals, the crew table and the driver cash work-out. `m` and `L` let the form preview unsaved values. */
function flMemoTotals(s, m = flMemo(s), L = flLegs(s.id)) {
  const km = s.endKm > s.startKm ? s.endKm - s.startKm : 0, fuelL = flSumBy(m.fuel.filter(f => f.type !== 'AdBlue'), f => f.ltrs), adblueL = flSumBy(m.fuel.filter(f => f.type === 'AdBlue'), f => f.ltrs), fuelAmt = flSumBy(m.fuel, f => f.amount);
  const billed = flSumBy(m.billed, x => x.amount), unbilled = flSumBy(m.unbilled, x => x.amount), advance = flSumBy(m.adv, x => x.amount), qty = flSumBy(L, l => l.qty), tripAmt = flSumBy(L, l => l.amt), doorAmt = flSumBy(m.door, x => x.amount);
  const d1 = L[0]?.driverId, d2 = L.find(l => l.driver2Id)?.driver2Id, cl = L.map(flCleaner).find(Boolean), ids = [...new Set(L.flatMap(flCrewIds))];
  const crew = ids.map(id => { const mine = L.filter(l => flCrewIds(l).includes(id)).map(l => flPayBase(l, id)), wage = flSumBy(mine, p => p.wage), batta = flSumBy(mine, p => p.batta), incentive = flNum(m.crew[id]?.incentive), timing = flNum(m.crew[id]?.timing), total = wage + batta + incentive + timing;
    const legacy = (id === d1 ? m.legacyPaid.d1 || 0 : 0) + (id === d2 ? m.legacyPaid.d2 || 0 : 0) + (id === cl ? m.legacyPaid.cl || 0 : 0);
    return { id, name: FL.name(id), role: mine[0]?.as === 'Cleaner' ? 'Cleaner' : 'Driver', trips: mine.length, solo: mine.filter(p => p.as === 'Driver (single)').length, wage, batta, incentive, timing, total, paid: m.payMode === 'sheet' ? total : Math.min(total, legacy) }; });
  const crewTotal = flSumBy(crew, c => c.total), crewOnSheet = m.payMode === 'sheet' ? crewTotal : 0, drvFuel = m.fuel.filter(f => f.pay === 'D'), drvFuelAmt = flSumBy(drvFuel, f => f.amount), drvExp = flSumBy([...m.billed, ...m.unbilled].filter(x => x.pay !== 'O'), x => x.amount);
  const collected = m.drvCollected + flSumBy(m.door.filter(x => x.payment === 'Driver'), x => x.amount), totalExp = fuelAmt + billed + unbilled + crewTotal, income = tripAmt + doorAmt + m.otherInc, balance = advance + collected - drvFuelAmt - drvExp - crewOnSheet;
  return { m, L, km, fuelL, adblueL, fuelAmt, billed, unbilled, exp: billed + unbilled, advance, qty, tripAmt, doorAmt, income, crew, crewTotal, crewOnSheet, drvFuelL: flSumBy(drvFuel, f => f.ltrs), drvFuelAmt, drvExp, collected, totalExp, balance, mileage: km && fuelL ? km / fuelL : 0, rsPerKm: km ? totalExp / km : 0, net: income - totalExp, filled: s.v === 2 || !!s.sheet };
}
const flSheetExp = s => flMemoTotals(s).exp;
const flSheetInc = s => flMemoTotals(s).income;
const flHrs = (a, b) => { if (!a || !b) return ''; const [h1, m1] = a.split(':').map(Number), [h2, m2] = b.split(':').map(Number); let d = h2 * 60 + m2 - h1 * 60 - m1; if (d < 0) d += 1440; return `${pad(Math.floor(d / 60))}:${pad(d % 60)}`; };

/* ---------- Print: laid out like a transport memo ---------- */
function flTripSheetPrint(s) {
  const v = FL.veh(s.vehicleId) || {}, T = flMemoTotals(s), m = T.m, L = T.L, n = x => flNum(x) ? flNum(x).toLocaleString('en-IN', { maximumFractionDigits: 2 }) : '0', dt = x => x ? fmtDate(x) : '', dates = L.map(l => l.date).sort(), box = (t, rows) => `<table class="ph-table mm-box">${t}${rows}</table>`;
  const rowsOr = (rows, cols) => rows || `<tr><td colspan="${cols}">&nbsp;</td></tr>`;
  openModal(`Memo ${s.id} · ${v.regNo || ''}`, `${printBar('memo')}<div class="print-sheet memo" data-landscape><section class="copy">
    <div class="mm-title">${esc(SITE_CONFIG.name)}</div>
    <div class="mm-head"><div class="mm-veh"><b>${esc(v.regNo || '')}</b><span class="mm-no">Memo No: ${esc(s.id)}</span><span>${esc([v.model, v.type].filter(Boolean).join(' · '))}</span><span>Insurance: ${dt(v.insuranceExpiry)}</span><span>Permit / fitness: ${dt(v.fitnessExpiry)}</span>${v.pucExpiry ? `<span>PUC: ${dt(v.pucExpiry)}</span>` : ''}</div>
      ${box('', `<tr><th>Starting KM</th><td class="r">${n(s.startKm)}</td></tr><tr><th>Ending KM</th><td class="r">${s.endKm ? n(s.endKm) : ''}</td></tr><tr><th>Total KM</th><td class="r"><b>${n(T.km)}</b></td></tr>`)}
      ${box('', `<tr><th>Date</th><td>${dates.length ? `${dt(dates[0])} to ${dt(dates[dates.length - 1])}` : dt(s.date)}</td></tr><tr><th>Diesel Avg</th><td>${T.mileage ? T.mileage.toFixed(2) + ' K.M' : ''}${m.target ? ` &nbsp; Target: ${m.target}` : ''}</td></tr><tr><th>Rs Per KM</th><td>${T.rsPerKm ? T.rsPerKm.toFixed(2) : ''}</td></tr>`)}</div>
    <table class="ph-table mm-trips"><tr><th>Date</th><th>Rno</th><th>Place</th><th>Seats / Lugg</th><th>Driver1</th><th>Driver2</th><th>Cleaner</th><th>KM</th><th>Hrs</th><th>Missing</th><th>Qty</th><th>Amt</th></tr>
      ${rowsOr(L.map(l => `<tr><td>${dt(l.date)}</td><td>${esc(l.rno || '')}</td><td><b>${esc(l.from || '')} To ${esc(l.to || '')}</b>${l.route ? `<span class="mm-via">${esc(l.route)}</span>` : ''}</td><td>${esc(l.load || '')}</td><td>${esc(FL.name(l.driverId))}</td><td>${esc(l.driver2Id ? FL.name(l.driver2Id) : '')}</td><td>${esc(flCleaner(l) ? FL.name(flCleaner(l)) : '')}</td><td class="r">${n(l.km)}</td><td class="r">${esc(l.hrs || flHrs(l.depTime, l.arrTime))}</td><td class="r">${n(l.missing)}</td><td class="r">${n(l.qty)}</td><td class="r"><b>${n(l.amt)}</b></td></tr>`).join(''), 12)}
      <tr><th colspan="7">Total</th><th class="r">${n(flSumBy(L, l => l.km))}</th><th></th><th class="r">${n(flSumBy(L, l => l.missing))}</th><th class="r">${n(T.qty)}</th><th class="r">${n(T.tripAmt)}</th></tr></table>
    <div class="mm-cols"><div class="mm-col">
        ${box('<tr><th>Date</th><th>Advance Branch</th><th>Details</th><th>Amount</th></tr>', rowsOr(m.adv.map(x => `<tr><td>${dt(x.date)}</td><td>${esc(x.branch || '')}</td><td>${esc(x.details || '')}</td><td class="r">${n(x.amount)}</td></tr>`).join(''), 4) + `<tr><th colspan="3">Total</th><th class="r">${n(T.advance)}</th></tr>`)}
        ${box('<tr><th>Date</th><th>Billed Exp</th><th>Pay</th><th>Amount</th></tr>', rowsOr(m.billed.map(x => `<tr><td>${dt(x.date)}</td><td>${esc(x.desc || '')}</td><td>${x.pay === 'O' ? 'O' : 'D'}</td><td class="r">${n(x.amount)}</td></tr>`).join(''), 4) + `<tr><th colspan="3">Total</th><th class="r">${n(T.billed)}</th></tr>`)}
        ${box('<tr><th>Date</th><th>UnBill Exp</th><th>Pay</th><th>Amount</th></tr>', rowsOr(m.unbilled.map(x => `<tr><td>${dt(x.date)}</td><td>${esc(x.desc || '')}</td><td>${x.pay === 'O' ? 'O' : 'D'}</td><td class="r">${n(x.amount)}</td></tr>`).join(''), 4) + `<tr><th colspan="3">Total</th><th class="r">${n(T.unbilled)}</th></tr>`)}
        <p class="mm-note">Pay: D = paid by the driver, O = paid by the office.</p></div>
      <div class="mm-col">
        ${box('<tr><th>Date</th><th>Type</th><th>Bunk</th><th>Ltrs/KG</th><th>Rate</th><th>Amount</th></tr>', rowsOr(m.fuel.map(x => `<tr><td>${dt(x.date)}</td><td>${esc(x.type)}${x.pay === 'D' ? ' (D)' : ''}</td><td>${esc(x.bunk || '')}</td><td class="r">${n(x.ltrs)}</td><td class="r">${n(x.rate)}</td><td class="r">${n(x.amount)}</td></tr>`).join(''), 6) + `<tr><th colspan="2">Total</th><th>AdBlue: ${n(T.adblueL)}</th><th class="r">${n(T.fuelL)}</th><th></th><th class="r">${n(T.fuelAmt)}</th></tr>`)}
        <div class="mm-check"><b>Checked &amp; Confirmed:</b><span>${[['tolls', 'Tools & Jack'], ['tax', 'Tax paper'], ['licence', 'Driver’s licence']].map(([k, l]) => `${m.checks[k] ? '☑' : '☐'} ${l}`).join(' &nbsp; ')}</span><b>Memo ${s.status === 'Closed' ? 'Closed @ ' + (s.closedAt ? fmtDateTime(s.closedAt) : '') : 'open'}</b></div>
        <div class="mm-sign"><div><b>Office Staff</b><i></i>Name: ${esc(s.closedBy || '')}</div><div><b>Driver Sign</b><i></i>Name: ${esc(L[0] ? FL.name(L[0].driverId) : '')}</div></div>
        ${box('<tr><th colspan="5" class="c">Door Delivery</th></tr><tr><th>G.C</th><th>Area</th><th>KM</th><th>Payment</th><th>Amount</th></tr>', rowsOr(m.door.map(x => `<tr><td>${esc(x.gc || '')}</td><td>${esc(x.area || '')}</td><td class="r">${n(x.km)}</td><td>${x.payment === 'Driver' ? 'Driver' : 'Office'}</td><td class="r">${n(x.amount)}</td></tr>`).join(''), 5))}</div>
      <div class="mm-col">
        ${box('<tr><th>Details</th><th>Amount</th></tr>', `<tr><td>Diesel [${n(T.fuelL)}] Ltrs/KG</td><td class="r">${n(T.fuelAmt)}</td></tr><tr><td>Billed Exp</td><td class="r">${n(T.billed)}</td></tr><tr><td>UnBill Exp</td><td class="r">${n(T.unbilled)}</td></tr><tr><td>Bata (Driver+Cleaner+Incentive)</td><td class="r">${n(T.crewTotal)}</td></tr><tr><th>Total Exp</th><th class="r">${n(T.totalExp)}</th></tr>${T.income ? `<tr><td>Total income</td><td class="r">${n(T.income)}</td></tr><tr><th>Income − Total Exp</th><th class="r">${n(T.net)}</th></tr>` : ''}`)}
        ${box('<tr><th>Driver Cash Work out</th><th>Amount</th></tr>', `<tr><td>Total Advance</td><td class="r">${n(T.advance)}</td></tr><tr><td>Seat/Lugg Payment</td><td class="r">${n(T.collected)}</td></tr><tr><td>Diesel/CNG/AdBlue [${n(T.drvFuelL)}] Ltrs</td><td class="r">${n(T.drvFuelAmt)}</td></tr><tr><td>Total Driver Exp</td><td class="r">${n(T.drvExp)}</td></tr>`)}
        ${box('<tr><th>Driver</th><th>Bata</th><th>Incentive</th><th>Timing</th></tr>', rowsOr(T.crew.map(c => `<tr><td>${esc(c.name)}${c.role === 'Cleaner' ? ' (C)' : ''}</td><td class="r">${n(c.wage + c.batta)}</td><td class="r">${n(c.incentive)}</td><td class="r">${n(c.timing)}</td></tr>`).join(''), 4) + `<tr><td colspan="3">Total Driver &amp; Cleaner${m.payMode === 'sheet' ? '' : ' (paid in payroll)'}</td><td class="r">${n(T.crewTotal)}</td></tr><tr><th colspan="3">Balance</th><th class="r">${T.balance.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</th></tr><tr><td colspan="3">${T.balance < 0 ? 'Cash to Driver' : 'Cash from Driver'}</td><td class="r">${n(Math.abs(T.balance))}</td></tr>`)}</div></div>
    </section></div>`, { wide: true, onMount: x => x.classList.add('modal-xl') });
}

/* ---------- The trip sheet form ---------- */
function flTripSheet(s, after) {
  const v = FL.veh(s.vehicleId) || {}, legs = flLegs(s.id).map(l => ({ ...l })), M = JSON.parse(JSON.stringify(flMemo(s))), H = { startKm: s.startKm || '', endKm: s.endKm || '' };
  if (!M.target) M.target = flNum(v.targetMileage); delete M.legacyPaid; M.legacyPaid = flMemo(s).legacyPaid;
  const today = todayISO(), blank = { adv: () => ({ date: today, branch: '', details: v.regNo || '', amount: '' }), billed: () => ({ date: today, desc: '', pay: 'D', amount: '' }), unbilled: () => ({ date: today, desc: '', pay: 'D', amount: '' }), fuel: () => ({ date: today, type: 'Diesel', bunk: '', ltrs: '', rate: M.fuel[M.fuel.length - 1]?.rate || '', amount: '', pay: 'C' }), door: () => ({ gc: '', area: '', km: '', payment: 'Driver', amount: '' }) };
  const inp = (path, val, type = 'text', extra = '') => `<input class="input mm-in" data-p="${path}" type="${type}" value="${esc(val ?? '')}" ${type === 'number' ? (extra.includes('data-neg') ? 'step="any"' : 'min="0" step="any"') : ''} ${extra}>`;
  const sel = (path, val, opts) => `<select class="input mm-in" data-p="${path}">${opts.map(o => { const [a, b] = Array.isArray(o) ? o : [o, o]; return `<option value="${esc(a)}" ${a === val ? 'selected' : ''}>${esc(b)}</option>`; }).join('')}</select>`;
  const payOpts = [['D', 'Driver'], ['O', 'Office']], del = (k, i) => `<td><button type="button" class="btn btn-sm btn-danger-ghost" data-del="${k}.${i}" aria-label="Remove row">×</button></td>`;
  const section = (k, title, head, row, addLabel) => `<div class="card stack mm-sec"><div class="mm-sec-head"><h4>${title}</h4><button type="button" class="btn btn-sm btn-outline" data-add="${k}">+ ${addLabel}</button></div><div class="table-wrap"><table class="table mm-table"><thead><tr>${head.map(h => `<th>${h}</th>`).join('')}<th></th></tr></thead><tbody>${M[k].map((x, i) => `<tr>${row(x, i)}${del(k, i)}</tr>`).join('') || `<tr><td class="empty" colspan="${head.length + 1}">None yet.</td></tr>`}</tbody></table></div></div>`;
  const expRow = k => (x, i) => `<td>${inp(`${k}.${i}.date`, x.date, 'date')}</td><td>${inp(`${k}.${i}.desc`, x.desc, 'text', 'list="dl-flexp" placeholder="Toll, entry fee…"')}</td><td>${sel(`${k}.${i}.pay`, x.pay, payOpts)}</td><td>${inp(`${k}.${i}.amount`, x.amount, 'number')}</td>`;
  const body = () => { const T = flMemoTotals({ ...s, startKm: flNum(H.startKm), endKm: flNum(H.endKm) }, M, legs);
    return `<datalist id="dl-flexp">${FL_EXP_HINTS.map(x => `<option value="${x}">`).join('')}</datalist>
    <div class="card mm-top"><label class="field"><span>Starting KM</span>${inp('H.startKm', H.startKm, 'number', 'required')}</label><label class="field"><span>Ending KM</span>${inp('H.endKm', H.endKm, 'number')}</label><label class="field"><span>Target mileage (km/L)</span>${inp('M.target', M.target || '', 'number')}</label><label class="field"><span>Crew bata is paid</span>${sel('M.payMode', M.payMode, [['sheet', 'On this memo (cash)'], ['payroll', 'In monthly payroll']])}</label></div>
    <div class="card stack mm-sec"><div class="mm-sec-head"><h4>Trips</h4><span class="muted small">Crew, places and timings are changed with “Edit” on the trip in the duty list.</span></div><div class="table-wrap"><table class="table mm-table"><thead><tr><th>Date</th><th>Rno</th><th>Place</th><th>Seats / Lugg</th><th>Crew</th><th>KM</th><th>Hrs</th><th>Missing</th><th>Qty</th><th>Amt (₹)</th></tr></thead><tbody>
      ${legs.map((l, i) => `<tr><td>${fmtDate(l.date)}</td><td>${inp(`L.${i}.rno`, l.rno, 'text', 'style="width:74px"')}</td><td><b>${esc(l.from)} → ${esc(l.to)}</b></td><td>${sel(`L.${i}.load`, l.load || '', ['', ...FL_LOADS])}</td><td class="small">${esc(flNames([l], x => [x.driverId, x.driver2Id]))}${flCleaner(l) ? '<br>' + esc(FL.name(flCleaner(l))) : ''}</td><td>${inp(`L.${i}.km`, l.km || '', 'number')}</td><td>${inp(`L.${i}.hrs`, l.hrs || flHrs(l.depTime, l.arrTime), 'text', 'placeholder="hh:mm" style="width:74px"')}</td><td>${inp(`L.${i}.missing`, l.missing || '', 'number')}</td><td>${inp(`L.${i}.qty`, l.qty || '', 'number')}</td><td>${inp(`L.${i}.amt`, l.amt || '', 'number')}</td></tr>`).join('') || '<tr><td class="empty" colspan="10">No trips added yet. Close this and click “+ Add trip”.</td></tr>'}</tbody></table></div></div>
    <div class="grid g2">${section('adv', 'Advance', ['Date', 'Advance branch', 'Details', 'Amount (₹)'], (x, i) => `<td>${inp(`adv.${i}.date`, x.date, 'date')}</td><td>${inp(`adv.${i}.branch`, x.branch, 'text', 'list="dl-india"')}</td><td>${inp(`adv.${i}.details`, x.details)}</td><td>${inp(`adv.${i}.amount`, x.amount, 'number')}</td>`, 'Add advance')}
      ${section('fuel', 'Diesel / AdBlue / CNG', ['Date', 'Type', 'Bunk', 'Ltrs/KG', 'Rate', 'Amount (₹)', 'Paid by'], (x, i) => `<td>${inp(`fuel.${i}.date`, x.date, 'date')}</td><td>${sel(`fuel.${i}.type`, x.type, FL_FUELS)}</td><td>${inp(`fuel.${i}.bunk`, x.bunk)}</td><td>${inp(`fuel.${i}.ltrs`, x.ltrs, 'number')}</td><td>${inp(`fuel.${i}.rate`, x.rate, 'number')}</td><td>${inp(`fuel.${i}.amount`, x.amount, 'number')}</td><td>${sel(`fuel.${i}.pay`, x.pay, [['C', 'Bunk credit'], ['D', 'Driver cash']])}</td>`, 'Add fuel')}
      ${section('billed', 'Billed expenses (with bill)', ['Date', 'Billed exp', 'Pay', 'Amount (₹)'], expRow('billed'), 'Add expense')}
      ${section('unbilled', 'Unbilled expenses (no bill)', ['Date', 'UnBill exp', 'Pay', 'Amount (₹)'], expRow('unbilled'), 'Add expense')}
      ${section('door', 'Door delivery', ['G.C', 'Area', 'KM', 'Payment', 'Amount (₹)'], (x, i) => `<td>${inp(`door.${i}.gc`, x.gc)}</td><td>${inp(`door.${i}.area`, x.area)}</td><td>${inp(`door.${i}.km`, x.km, 'number')}</td><td>${sel(`door.${i}.payment`, x.payment, [['Driver', 'Collected by driver'], ['Office', 'Paid at office']])}</td><td>${inp(`door.${i}.amount`, x.amount, 'number')}</td>`, 'Add delivery')}
      <div class="card stack mm-sec"><div class="mm-sec-head"><h4>Driver &amp; cleaner</h4></div><div class="table-wrap"><table class="table mm-table"><thead><tr><th>Name</th><th>Bata (wage + bata)</th><th>Incentive (₹)</th><th>Timing (₹)</th></tr></thead><tbody>${T.crew.map(c => `<tr><td><b>${esc(c.name)}</b><div class="muted small">${c.role} · ${c.trips} trip${c.trips === 1 ? '' : 's'}</div></td><td>${inr(c.wage + c.batta)}</td><td>${inp(`crew.${c.id}.incentive`, M.crew[c.id]?.incentive || '', 'number')}</td><td>${inp(`crew.${c.id}.timing`, M.crew[c.id]?.timing || '', 'number', 'data-neg placeholder="− for a cut"')}</td></tr>`).join('') || '<tr><td class="empty" colspan="4">Add a trip to see its crew.</td></tr>'}</tbody></table></div>
        <div class="form-grid" style="grid-template-columns:1fr 1fr"><label class="field"><span>Seat / luggage payment with driver (₹)</span>${inp('M.drvCollected', M.drvCollected || '', 'number')}</label><label class="field"><span>Other income (₹)</span>${inp('M.otherInc', M.otherInc || '', 'number')}</label></div>
        <div class="chips">${[['tolls', 'Tools & jack'], ['tax', 'Tax paper'], ['licence', 'Driver’s licence']].map(([k, l]) => `<label class="check"><input type="checkbox" data-chk="${k}" ${M.checks[k] ? 'checked' : ''}> ${l}</label>`).join('')}</div></div></div>
    <div id="mm-sum"></div>`; };
  const sums = m => { const T = flMemoTotals({ ...s, startKm: flNum(H.startKm), endKm: flNum(H.endKm) }, M, legs), li = (a, b, cls = '') => `<div class="line-item ${cls}"><span>${a}</span><span>${b}</span></div>`;
    $('#mm-sum', m).innerHTML = `<div class="grid g3"><div class="card" style="background:var(--surface-2)"><h4>Running</h4>${li('Total KM', T.km.toLocaleString('en-IN'))}${li('Diesel average', T.mileage ? T.mileage.toFixed(2) + ' km/L' + (M.target ? (T.mileage >= M.target ? ' ✓ on target' : ' · below target ' + M.target) : '') : '—')}${li('Rs per KM', T.rsPerKm ? '₹' + T.rsPerKm.toFixed(2) : '—')}${li('Quantity', T.qty.toLocaleString('en-IN'))}${li('Trip amount', inr(T.tripAmt))}${li('Income − Total exp', inr(T.net), 'total')}</div>
      <div class="card" style="background:var(--surface-2)"><h4>Details</h4>${li(`Diesel [${Math.round(T.fuelL * 100) / 100}] Ltrs/KG`, inr(T.fuelAmt))}${li('Billed exp', inr(T.billed))}${li('UnBill exp', inr(T.unbilled))}${li('Bata (driver + cleaner + incentive)', inr(T.crewTotal))}${li('Total exp', inr(T.totalExp), 'total')}</div>
      <div class="card" style="background:var(--surface-2)"><h4>Driver cash work-out</h4>${li('Total advance', inr(T.advance))}${li('Seat / lugg payment', inr(T.collected))}${li(`Diesel paid by driver [${Math.round(T.drvFuelL * 100) / 100}] Ltrs`, '− ' + inr(T.drvFuelAmt))}${li('Total driver exp', '− ' + inr(T.drvExp))}${li(M.payMode === 'sheet' ? 'Total driver & cleaner' : 'Driver & cleaner (in payroll)', M.payMode === 'sheet' ? '− ' + inr(T.crewTotal) : '—')}${li(T.balance < 0 ? 'Cash to driver' : 'Cash from driver', inr(Math.abs(T.balance)), 'total')}</div></div>`; };
  openModal(`Memo ${s.id} · ${v.regNo || ''}`, `<form id="ts" class="stack memo-form"><div id="mm-body"></div><div style="display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap"><span class="muted small" style="margin-right:auto;align-self:center">Entering the Ending KM closes the memo and updates the vehicle’s odometer.</span><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-outline" name="go" value="save">Save</button><button class="btn btn-primary" name="go" value="print">Save and print</button></div></form>`, { wide: true, onMount: m => {
    const f = $('#ts', m), draw = () => { $('#mm-body', m).innerHTML = body(); sums(m); }; m.classList.add('modal-xl'); draw();
    const put = (p, val) => { const [a, b, c] = p.split('.'); if (a === 'H') H[b] = val; else if (a === 'M') M[b] = b === 'payMode' ? val : flNum(val); else if (a === 'L') legs[+b][c] = ['rno', 'load', 'hrs'].includes(c) ? val : flNum(val); else if (a === 'crew') (M.crew[b] = M.crew[b] || {})[c] = flNum(val); else M[a][+b][c] = ['amount', 'ltrs', 'rate', 'km'].includes(c) ? (val === '' ? '' : flNum(val)) : val; };
    f.addEventListener('input', e => { const t = e.target; if (t.dataset.chk) { M.checks[t.dataset.chk] = t.checked; return; } if (!t.dataset.p) return; put(t.dataset.p, t.value);
      const [a, i, c] = t.dataset.p.split('.'); if (a === 'fuel' && (c === 'ltrs' || c === 'rate')) { const r = M.fuel[+i]; if (flNum(r.ltrs) && flNum(r.rate)) { r.amount = Math.round(r.ltrs * r.rate * 100) / 100; const am = $(`[data-p="fuel.${i}.amount"]`, f); if (am) am.value = r.amount; } }
      if (a === 'fuel' && c === 'amount') { const r = M.fuel[+i]; if (flNum(r.ltrs) && flNum(r.amount) && !flNum(r.rate)) { r.rate = Math.round(r.amount / r.ltrs * 100) / 100; const rt = $(`[data-p="fuel.${i}.rate"]`, f); if (rt) rt.value = r.rate; } }
      sums(m); });
    f.addEventListener('click', e => { const add = e.target.closest('[data-add]'), rm = e.target.closest('[data-del]'); if (add) { M[add.dataset.add].push(blank[add.dataset.add]()); draw(); const rows = $$(`[data-p^="${add.dataset.add}."]`, f); rows[rows.length - (add.dataset.add === 'fuel' ? 5 : add.dataset.add === 'door' ? 5 : 3)]?.focus(); } if (rm) { const [k, i] = rm.dataset.del.split('.'); M[k].splice(+i, 1); draw(); } });
    f.onsubmit = e => { e.preventDefault(); const start = flNum(H.startKm), end = flNum(H.endKm); if (end && end < start) return toast(`Ending KM (${end}) cannot be less than the Starting KM (${start})`, 'err'); if (end && !legs.length) return toast('Add at least one trip to this memo before closing it', 'err');
      const keep = a => a.filter(x => flNum(x.amount) || flNum(x.ltrs) || x.desc || x.gc || x.area).map(x => ({ ...x, amount: flNum(x.amount), ...(x.ltrs !== undefined ? { ltrs: flNum(x.ltrs), rate: flNum(x.rate) } : {}), ...(x.km !== undefined ? { km: flNum(x.km) } : {}) }));
      const done = end > 0, was = s.status === 'Closed', doc = { v: 2, startKm: start, endKm: end, adv: keep(M.adv), billed: keep(M.billed), unbilled: keep(M.unbilled), fuel: keep(M.fuel), door: keep(M.door), crew: M.crew, payMode: M.payMode, drvCollected: flNum(M.drvCollected), otherInc: flNum(M.otherInc), target: flNum(M.target), checks: M.checks, sheet: { v: 2 }, status: done ? 'Closed' : s.status, ...(done && !was ? { closedAt: new Date().toISOString(), closedBy: Auth.user()?.name || '' } : {}) };
      legs.forEach(l => FL.upd('duties', l.id, { rno: l.rno || '', load: l.load || '', km: flNum(l.km), hrs: l.hrs || '', missing: flNum(l.missing), qty: flNum(l.qty), amt: flNum(l.amt) }));
      FL.upd('sheets', s.id, doc); if (flNum(M.target) && v.id && flNum(v.targetMileage) !== flNum(M.target)) Store.update('vehicles', v.id, { targetMileage: flNum(M.target) });
      const fresh = FL.find('sheets', s.id); if (done) flFinishTrip(fresh, end);
      closeModal(); toast(done ? `${s.id} saved · ${(end - start).toLocaleString('en-IN')} km · memo closed` : `${s.id} saved`); after && after(); if (e.submitter?.value === 'print') flTripSheetPrint(fresh); }; } });
}

/* ---------- Payroll ---------- */
function flPayroll(body, again) {
  if (flNeedsApi(body)) return; flMigrate();
  const mon = Session.get('flPayMonth') || todayISO().slice(0, 7), S = FL.list('staff').filter(s => s.status === 'Active'), PR = FL.list('payroll').filter(p => p.month === mon), days = new Date(+mon.slice(0, 4), +mon.slice(5, 7), 0).getDate();
  const role = id => FL.find('staff', id)?.role || '', sum = f => PR.reduce((s, p) => s + (+f(p) || 0), 0), crew = ['Driver', 'Conductor', 'Cleaner'], closed = () => FL.list('sheets').filter(s => s.status === 'Closed' && String(s.date).startsWith(mon)).sort((a, b) => a.date.localeCompare(b.date)).map(s => ({ s, T: flMemoTotals(s) }));
  const netOf = p => Math.max(0, (+p.earned || 0) + (+p.batta || 0) + (+p.bonus || 0) - (+p.tripPaid || 0) - (+p.advance || 0) - (+p.deduction || 0));
  body.innerHTML = `<div style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-bottom:12px"><label class="field"><span>Month</span><input class="input" type="month" id="fp-mon" value="${mon}"></label><button class="btn btn-primary" id="fp-gen">${PR.length ? 'Recalculate from memos' : 'Generate payroll'}</button></div>
    <div class="kpis" style="margin-bottom:14px">${kpi('Staff on payroll', PR.length)}${kpi('Earned on trips', inr(sum(p => crew.includes(role(p.staffId)) ? (+p.earned || 0) + (+p.batta || 0) : 0)), `${inr(sum(p => p.tripPaid))} already paid on memos`)}${kpi('Drivers', inr(sum(p => role(p.staffId) === 'Driver' ? p.net : 0)), 'still to pay')}${kpi('Cleaners', inr(sum(p => ['Conductor', 'Cleaner'].includes(role(p.staffId)) ? p.net : 0)), 'still to pay')}${kpi('Office & others', inr(sum(p => !crew.includes(role(p.staffId)) ? p.net : 0)))}${kpi('Net payable', inr(sum(p => p.net)), `${inr(sum(p => p.status === 'Paid' ? p.net : 0))} paid`)}</div>
    <div class="table-wrap"><table class="table"><thead><tr><th>Staff</th><th>Basis</th><th>Wages</th><th>Bata + incentive</th><th>Paid on memos</th><th>Bonus</th><th>Advance</th><th>Other deductions</th><th>Net pay</th><th>Status</th><th></th></tr></thead><tbody>
    ${PR.sort((a, b) => FL_ROLES.indexOf(role(a.staffId)) - FL_ROLES.indexOf(role(b.staffId))).map(p => `<tr><td><b>${esc(FL.name(p.staffId))}</b><div class="muted small">${esc(role(p.staffId))}</div></td><td>${esc(p.basis)}</td><td>${inr(p.earned)}</td><td>${inr(p.batta)}</td><td>${p.tripPaid ? '− ' + inr(p.tripPaid) : '—'}</td><td>${inr(p.bonus)}</td><td>${inr(p.advance)}</td><td>${inr(p.deduction)}</td><td><b>${inr(p.net)}</b></td><td><span class="chip ${p.status === 'Paid' ? 'green' : 'warn'}">${p.status}</span></td><td class="row-actions">${p.status === 'Paid' ? '' : `<button class="btn btn-sm btn-ghost" data-adj="${p.id}">Adjust</button><button class="btn btn-sm btn-green" data-pay="${p.id}">Pay</button>`}<button class="btn btn-sm btn-ghost" data-slip="${p.id}">Payslip</button></td></tr>`).join('') || '<tr><td class="empty" colspan="11">No payroll for this month yet. Click “Generate payroll”.</td></tr>'}</tbody></table></div>
    <p class="muted small" style="margin-top:10px">Drivers and cleaners earn the wage and bata of each trip on a <b>closed</b> memo, plus any incentive and timing amount entered on it. When a memo settles the crew in cash (“Cash to driver”), that amount shows under “Paid on memos” and is not paid again here. Office staff get their monthly salary less unpaid leave days. Advances not yet recovered are deducted and marked recovered when the salary is paid.</p>`;
  $('#fp-mon', body).onchange = e => { Session.set('flPayMonth', e.target.value); again(); };
  $('#fp-gen', body).onclick = () => { const C = closed(), A = FL.list('advances').filter(a => !a.recovered && a.date.slice(0, 7) <= mon); let n = 0;
    S.forEach(s => { const id = `${s.id}_${mon}`, old = FL.find('payroll', id); if (old?.status === 'Paid') return;
      const mine = C.map(x => x.T.crew.find(c => c.id === s.id)).filter(Boolean), lop = old?.lop || 0, bonus = old?.bonus || 0, deduction = old?.deduction || 0, trips = flSumBy(mine, c => c.trips), solo = flSumBy(mine, c => c.solo), monthly = s.payType === 'Monthly';
      const earned = monthly ? Math.round(s.monthlySalary - s.monthlySalary / days * lop) : flSumBy(mine, c => c.wage), batta = monthly ? 0 : flSumBy(mine, c => c.batta + c.incentive + c.timing), tripPaid = monthly ? 0 : flSumBy(mine, c => c.paid), advance = A.filter(a => a.staffId === s.id).reduce((t, a) => t + a.amount, 0);
      const p = { staffId: s.id, month: mon, basis: monthly ? `Monthly ${inr(s.monthlySalary)}${lop ? ` · ${lop} unpaid day(s)` : ''}` : `${trips} trip${trips === 1 ? '' : 's'}${solo ? ` · ${solo} alone` : ''}`, duties: trips, lop, earned, batta, tripPaid, bonus, advance, deduction, status: 'Pending' }; p.net = netOf(p); FL.put('payroll', id, p); n++; });
    toast(`Payroll calculated for ${n} staff`); again(); };
  $$('[data-adj]', body).forEach(b => b.onclick = () => { const p = FL.find('payroll', b.dataset.adj), s = FL.find('staff', p.staffId);
    openModal(`Adjust · ${s.name}`, `<form id="fx" class="form-grid"><label class="field"><span>Bonus / overtime / incentive (₹)</span><input class="input" type="number" name="bonus" min="0" value="${p.bonus}"></label><label class="field"><span>Other deductions: fines, damage, PF (₹)</span><input class="input" type="number" name="ded" min="0" value="${p.deduction}"></label>${s.payType === 'Monthly' ? `<label class="field"><span>Unpaid leave days</span><input class="input" type="number" name="lop" min="0" max="${days}" step="0.5" value="${p.lop || 0}"></label>` : ''}<button class="btn btn-primary full">Save</button></form>`, { onMount: m => $('#fx', m).onsubmit = e => { e.preventDefault(); const t = e.target, bonus = +t.bonus.value, deduction = +t.ded.value, lop = +(t.lop?.value || 0), earned = s.payType === 'Monthly' ? Math.round(s.monthlySalary - s.monthlySalary / days * lop) : p.earned;
      FL.upd('payroll', p.id, { bonus, deduction, lop, earned, basis: s.payType === 'Monthly' ? `Monthly ${inr(s.monthlySalary)}${lop ? ` · ${lop} unpaid day(s)` : ''}` : p.basis, net: netOf({ ...p, bonus, deduction, earned }) }); closeModal(); again(); } }); });
  $$('[data-pay]', body).forEach(b => b.onclick = () => { const p = FL.find('payroll', b.dataset.pay); FL.upd('payroll', p.id, { status: 'Paid', paidOn: todayISO() }); FL.list('advances').filter(a => a.staffId === p.staffId && !a.recovered && a.date.slice(0, 7) <= mon).forEach(a => FL.upd('advances', a.id, { recovered: true, recoveredIn: mon })); toast(`${inr(p.net)} paid to ${FL.name(p.staffId)}`); again(); });
  $$('[data-slip]', body).forEach(b => b.onclick = () => { const p = FL.find('payroll', b.dataset.slip), s = FL.find('staff', p.staffId), D = closed().map(x => ({ ...x, c: x.T.crew.find(c => c.id === s.id) })).filter(x => x.c);
    openModal(`Payslip · ${s.name}`, `${printBar('payslip')}<div class="print-sheet"><section class="copy"><header><div class="ph-brand"><b>${esc(SITE_CONFIG.name)} · Fleet</b><span>${esc(SITE_CONFIG.address)}</span></div><div class="ph-kind"><b>PAYSLIP</b><span>${new Date(mon + '-01T00:00:00').toLocaleDateString('en-IN', { month: 'long', year: 'numeric' })}</span></div></header>
      <div class="ph-grid"><div><span>Employee</span><b>${esc(s.name)}</b>${esc(s.role)} · ${esc(s.phone)}</div><div><span>Pay basis</span><b>${esc(p.basis)}</b>${s.bank ? 'Bank a/c ' + esc(s.bank) + (s.ifsc ? ' · ' + esc(s.ifsc) : '') : ''}</div></div>
      <table class="ph-table"><tr><th>Earnings</th><th>Amount</th><th>Deductions</th><th>Amount</th></tr><tr><td>${s.payType === 'Monthly' ? 'Salary' : 'Trip wages'}</td><td>${inr(p.earned)}</td><td>Paid in cash on memos</td><td>${inr(p.tripPaid)}</td></tr><tr><td>Trip bata, incentive, timing</td><td>${inr(p.batta)}</td><td>Advance recovered</td><td>${inr(p.advance)}</td></tr><tr><td>Bonus / incentive</td><td>${inr(p.bonus)}</td><td>Other deductions</td><td>${inr(p.deduction)}</td></tr><tr><th>Total earnings</th><th>${inr(p.earned + p.batta + p.bonus)}</th><th>Net pay</th><th>${inr(p.net)}</th></tr></table>
      ${D.length ? `<table class="ph-table"><tr><th>Date</th><th>Memo</th><th>Vehicle</th><th>Trips</th><th>Wage + bata</th><th>Incentive</th><th>Timing</th><th>Paid on trip</th></tr>${D.map(x => `<tr><td>${fmtDate(x.s.date)}</td><td>${esc(x.s.id)}</td><td class="mono">${esc(FL.veh(x.s.vehicleId)?.regNo || '')}</td><td>${esc(flChain(x.T.L.filter(l => flCrewIds(l).includes(s.id))))}</td><td>${inr(x.c.wage + x.c.batta)}</td><td>${inr(x.c.incentive)}</td><td>${inr(x.c.timing)}</td><td>${inr(x.c.paid)}</td></tr>`).join('')}</table>` : ''}
      <div class="ph-sign"><div><span>Employee signature</span><i></i></div><div><span>For ${esc(SITE_CONFIG.name)}</span><i></i>${p.status === 'Paid' ? 'Paid on ' + fmtDate(p.paidOn) : 'Authorised signatory'}</div></div></section></div>`, { wide: true }); });
}
